<?php
namespace Kitgenix\MultiStore\Privacy;

final class Privacy {
    public function hooks():void{add_filter('wp_privacy_personal_data_exporters',array($this,'exporters'));add_filter('wp_privacy_personal_data_erasers',array($this,'erasers'));}
    public function exporters(array$e):array{$e['kitgenix-multistore']=array('exporter_friendly_name'=>__('Kitgenix MultiStore network data','kitgenix-multistore'),'callback'=>array($this,'export'));return$e;}
    public function erasers(array$e):array{$e['kitgenix-multistore']=array('eraser_friendly_name'=>__('Kitgenix MultiStore network data','kitgenix-multistore'),'callback'=>array($this,'erase'));return$e;}
    public function export(string$email,int$page=1):array{global$wpdb;$data=array();$orders=$wpdb->get_results($wpdb->prepare("SELECT network_id,store_uuid,order_number,status,currency,total,customer_name,order_created_at FROM {$wpdb->prefix}kitgenix_multistore_sync_for_woocommerce_remote_orders WHERE customer_email=%s",$email),ARRAY_A)?:array();foreach($orders as$o){$data[]=array('group_id'=>'kitgenix-multistore-sync-for-woocommerce-orders','group_label'=>__('MultiStore Orders','kitgenix-multistore'),'item_id'=>'order-'.$o['network_id'],'data'=>array_map(static fn($k,$v)=>array('name'=>ucwords(str_replace('_',' ',$k)),'value'=>$v),array_keys($o),array_values($o)));}$customers=$wpdb->get_results($wpdb->prepare("SELECT network_id,store_uuid,email,display_name,synced_at FROM {$wpdb->prefix}kitgenix_multistore_sync_for_woocommerce_customers WHERE email=%s",$email),ARRAY_A)?:array();foreach($customers as$c){$data[]=array('group_id'=>'kitgenix-multistore-sync-for-woocommerce-customers','group_label'=>__('MultiStore Customer Data','kitgenix-multistore'),'item_id'=>'customer-'.$c['network_id'].'-'.$c['store_uuid'],'data'=>array_map(static fn($k,$v)=>array('name'=>ucwords(str_replace('_',' ',$k)),'value'=>$v),array_keys($c),array_values($c)));}return array('data'=>$data,'done'=>true);}
    public function erase(string$email,int$page=1):array{global$wpdb;$orders=$wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}kitgenix_multistore_sync_for_woocommerce_remote_orders SET customer_email='',customer_name='',payload='{}' WHERE customer_email=%s",$email));$customers=$wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->prefix}kitgenix_multistore_sync_for_woocommerce_customers WHERE email=%s",$email));return array('items_removed'=>(bool)($orders||$customers),'items_retained'=>false,'messages'=>array(),'done'=>true);}
}
